'use strict';

document.addEventListener('DOMContentLoaded', function () {
    const photos = window.CAMERA_PHOTOS || [];
    const shutter = document.getElementById('cameraShutter');
    const paper = document.querySelector('.info-content');
    const photo = document.querySelector('.info-photo');
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    const interval = 5000;
    let currentPhoto = 0;
    let busy = false;
    let timer;
    let hovered = false;
    let focused = paper.contains(document.activeElement);

    if (photos.length === 0) {
        photo.setAttribute('aria-label', '暂无相片');
        shutter.disabled = true;
        return;
    }
    photo.style.backgroundImage = `url("${photos[0].src}")`;
    photo.setAttribute('aria-label', photos[0].description);
    if (photos.length === 1) {
        shutter.disabled = true;
        return;
    }

    function paused() {
        return hovered || focused || document.hidden || reducedMotion.matches;
    }

    function schedule() {
        clearTimeout(timer);
        if (!busy && !paused()) {
            timer = setTimeout(() => changePhoto(true), interval);
        }
    }

    async function changePhoto(automatic = false) {
        if (busy || (automatic && paused())) return;
        clearTimeout(timer);
        busy = true;
        shutter.setAttribute('aria-disabled', 'true');
        let layer;
        let animation;
        try {
            const nextPhoto = (currentPhoto + 1) % photos.length;
            const image = new Image();
            image.src = photos[nextPhoto].src;
            await image.decode();
            // A hover, focus or hidden tab may have paused playback while loading.
            if (automatic && paused()) return;

            if (!reducedMotion.matches) {
                layer = document.createElement('div');
                layer.className = 'photo-next';
                layer.setAttribute('aria-hidden', 'true');
                layer.style.backgroundImage = `url("${image.src}")`;
                photo.appendChild(layer);
                animation = layer.animate([{ opacity: 0 }, { opacity: 1 }], {
                    duration: 700, easing: 'ease-in-out', fill: 'forwards'
                });
                await animation.finished;
            }
            photo.style.backgroundImage = `url("${image.src}")`;
            photo.setAttribute('aria-label', photos[nextPhoto].description);
            currentPhoto = nextPhoto;
        } catch (error) {
            console.warn('Could not change the camera photo.', error);
        } finally {
            if (animation) animation.cancel();
            if (layer) layer.remove();
            shutter.removeAttribute('aria-disabled');
            busy = false;
            schedule();
        }
    }

    shutter.addEventListener('click', () => changePhoto());
    paper.addEventListener('mouseenter', function () {
        hovered = true;
        schedule();
    });
    paper.addEventListener('mouseleave', function () {
        hovered = false;
        schedule();
    });
    paper.addEventListener('focusin', function () {
        focused = true;
        schedule();
    });
    paper.addEventListener('focusout', function (event) {
        focused = paper.contains(event.relatedTarget);
        schedule();
    });
    document.addEventListener('visibilitychange', schedule);
    reducedMotion.addEventListener('change', schedule);
    schedule();
    console.log('©umm233 2018-' + new Date().getFullYear());
}, { once: true });
